<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetContentVO;

trait ThemeAssetContentAttributeHolder
{
    protected ThemeAssetContentVO|string|null $content = null;
    protected bool $contentAssigned = false;

    public function getContentOrCurrent(ThemeAssetContentVO $content): ThemeAssetContentVO
    {
        if ($this->contentAssigned) {
            \assert(null !== $this->content);
            return ThemeAssetContentVO::from($this->content);
        } else {
            return $content;
        }
    }
    public function contentTryBuildInitial(ConstraintFailList $error): ?ThemeAssetContentVO
    {
        return  ThemeAssetContentVO::tryFrom($this->contentAssigned ? $this->content : null, $error);
    }
    public function content(ThemeAssetContentVO|string $content): static
    {
        $this->content = $content;
        $this->contentAssigned = true;
        return $this;
    }
    public function getContent(): ?string
    {
        return $this->content instanceof ThemeAssetContentVO ? $this->content->value() : $this->content;
    }
    public function isContentAssigned(): bool
    {
        return $this->contentAssigned;
    }
    public function writeContentTo(mixed $att): void
    {
        if ($this->contentAssigned) {
            \assert(null !== $this->content);
            $att->content($this->content);
        }
    }
    public function readContentFrom(mixed $att): void
    {
        if ($att->isContentAssigned()) {
            $content = $att->getContent();
            \assert(null !== $content);
            $this->content($content);
        }
    }
    public function unsetContent(): static
    {
        $this->contentAssigned = false;
        return $this;
    }
    protected function withDefaultContent(): void
    {
    }
    protected function withAssertedContentRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->contentAssigned = $this->contentAssigned) {
            $value->content = ThemeAssetContentVO::tryFrom($this->content, $errorsList);
        }
    }
}
